card_css:
/* Variante 1: Clássico Brutalismo Agressivo */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 3px solid var(--sl-text-main);
  border-radius: 0;
  box-shadow: 8px 8px 0 0 var(--sl-primary);
  transition: all 0.2s ease-in-out;
}
.sl-card:hover {
  box-shadow: 12px 12px 0 0 var(--sl-primary);
  transform: translate(-4px, -4px);
  border-color: var(--sl-primary);
}

/* Variante 2: Brutalismo Dupla Exposição */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 2px solid var(--sl-text-main);
  border-radius: 0;
  box-shadow: 6px 6px 0 0 var(--sl-primary), 12px 12px 0 0 var(--sl-text-main);
  transition: all 0.3s ease-in-out;
}
.sl-card:hover {
  box-shadow: 6px 6px 0 0 var(--sl-text-main), 12px 12px 0 0 var(--sl-primary);
  transform: translate(-3px, -3px);
}

/* Variante 3: Minimalista Brutalista de Contorno */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 4px solid var(--sl-text-main);
  border-radius: 0;
  box-shadow: 4px 4px 0 0 var(--sl-primary);
  transition: all 0.2s linear;
}
.sl-card:hover {
  border-color: var(--sl-primary);
  box-shadow: 0 0 0 0 transparent; /* Remove external shadow */
  outline: 4px solid var(--sl-primary); /* Add an outline on hover */
  outline-offset: 4px;
}

/* Variante 4: Brutalismo Assimétrico */
.sl-card {
  background-color: var(--sl-card-bg);
  border-top: 5px solid var(--sl-text-main);
  border-left: 5px solid var(--sl-text-main);
  border-right: 2px solid var(--sl-primary);
  border-bottom: 2px solid var(--sl-primary);
  border-radius: 0;
  box-shadow: 6px 6px 0 0 var(--sl-primary);
  transition: all 0.2s ease-out;
}
.sl-card:hover {
  transform: translateX(-3px) translateY(-3px) skewX(1deg);
  border-color: var(--sl-primary);
  box-shadow: 10px 10px 0 0 var(--sl-text-main);
}

/* Variante 5: Brutalismo Geométrico de Grade */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 1px dashed var(--sl-text-main);
  border-radius: 0;
  box-shadow: 7px 7px 0 0 var(--sl-primary);
  transition: all 0.2s ease-in-out;
}
.sl-card:hover {
  border: 1px dashed var(--sl-primary);
  box-shadow: 0 0 0 0 transparent;
  transform: translate(7px, 7px);
}

/* Variante Nova 1: Frosted Terminal Brutalism */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 3px solid var(--sl-text-main);
  box-shadow: inset 0 0 10px rgba(var(--sl-primary-rgb), 0.1), 0px 0px 0px 5px var(--sl-bg-body), 10px 10px 0px 5px var(--sl-primary);
  padding: 1.5rem;
  transition: all 0.3s ease;
  font-family: 'Space Mono', monospace;
  text-transform: uppercase;
}
.sl-card:hover {
  box-shadow: inset 0 0 15px rgba(var(--sl-primary-rgb), 0.3), 0px 0px 0px 5px var(--sl-bg-body), 15px 15px 0px 5px var(--sl-primary);
  transform: translate(-5px, -5px);
  border-color: var(--sl-primary);
}
.sl-card .card-title {
  color: var(--sl-primary);
  font-weight: 700;
}

/* Variante Nova 2: Brutalismo Neumórfico Chiselado */
.sl-card {
  background-color: var(--sl-card-bg);
  border: none;
  box-shadow: 10px 10px 0px 0px var(--sl-bg-body), -10px -10px 0px 0px var(--sl-text-main);
  padding: 1.5rem;
  transition: all 0.3s ease;
  text-transform: uppercase;
}
.sl-card:hover {
  box-shadow: inset 5px 5px 10px var(--sl-bg-body), inset -5px -5px 10px var(--sl-text-main), 0px 0px 0px 3px var(--sl-primary);
  transform: translateY(2px);
}
.sl-card .card-title {
  color: var(--sl-primary);
  font-weight: 700;
  letter-spacing: 1px;
}

/* Variante Nova 3: Brutalismo Glitch Digital */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 3px dashed var(--sl-text-main);
  box-shadow: 5px 5px 0 var(--sl-primary), -5px -5px 0 var(--sl-text-main), 0 0 0 1px var(--sl-primary);
  padding: 1.5rem;
  transition: all 0.1s linear;
  text-transform: uppercase;
}
.sl-card:hover {
  transform: translate(2px, -2px) skewX(2deg);
  box-shadow: 8px 8px 0 var(--sl-primary), -8px -8px 0 var(--sl-text-main), 0 0 0 2px var(--sl-primary);
  border-color: var(--sl-primary);
}
.sl-card .card-title {
  color: var(--sl-primary);
  font-weight: 900;
  text-shadow: 2px 2px 0 var(--sl-text-main);
}

/* Variante Nova 4: Brutalismo de Esquema (Diagrammatic Brutalism) */
.sl-card {
  background-color: var(--sl-card-bg);
  border: 0;
  border-bottom: 5px solid var(--sl-text-main);
  border-left: 5px solid var(--sl-text-main);
  background-image: radial-gradient(var(--sl-text-main) 1px, transparent 1px);
  background-size: 10px 10px;
  box-shadow: 10px 10px 0px 0px var(--sl-primary);
  padding: 1.5rem;
  transition: all 0.3s ease;
  text-transform: uppercase;
}
.sl-card:hover {
  border-bottom-color: var(--sl-primary);
  border-left-color: var(--sl-primary);
  box-shadow: 15px 15px 0px 0px var(--sl-primary);
  transform: translate(-5px, -5px);
}
.sl-card .card-title {
  color: var(--sl-text-main);
  font-weight: 800;
}
.sl-card .card-footer {
  border-top: 2px dashed var(--sl-text-main);
  padding-top: 1rem;
  margin-top: 1rem;
}

/* Variante Nova 5: Brutalismo de Placa de Circuito (Circuit Board Brutalism) */
.sl-card {
  background-color: var(--sl-card-bg);
  background-image: linear-gradient(0deg, rgba(var(--sl-text-main-rgb), 0.05) 1px, transparent 1px),
                    linear-gradient(90deg, rgba(var(--sl-text-main-rgb), 0.05) 1px, transparent 1px);
  background-size: 20px 20px;
  border: 5px outset var(--sl-text-main);
  box-shadow: inset 0 0 15px rgba(var(--sl-text-main-rgb), 0.2), 15px 15px 0px 0px var(--sl-bg-body);
  padding: 1.5rem;
  transition: all 0.3s ease;
  text-transform: uppercase;
}
.sl-card:hover {
  border: 5px inset var(--sl-primary);
  box-shadow: inset 0 0 25px rgba(var(--sl-primary-rgb), 0.4), 10px 10px 0px 0px var(--sl-bg-body);
  transform: translate(5px, 5px);
}
.sl-card .card-title {
  color: var(--sl-primary);
  font-weight: 900;
  text-shadow: 1px 1px 0 var(--sl-text-main);
}
.sl-card .badge {
  background-color: var(--sl-primary);
  color: var(--sl-card-bg);
  border-radius: 0;
  padding: .5em .75em;
  font-weight: 700;
}
